    private static function save(string $bytes,string $ext,string $prefix):string{$ext=preg_replace('/[^a-z0-9]+/i','',$ext)?:'bin';$path=self::mediaDir().'/'.$prefix.'-'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(5)).'.'.$ext;if(file_put_contents($path,$bytes,LOCK_EX)===false)throw new RuntimeException('media_file_write_failed');@chmod($path,0600);return $path;}
    public static function transcribe(string $path,?string $model=null):array{if(!is_file($path)||filesize($path)===0)throw new RuntimeException('audio_file_missing');if(filesize($path)>25*1024*1024)throw new RuntimeException('audio_file_too_large');$model=trim((string)$model)?:'gpt-4o-mini-transcribe';$ch=curl_init('https://api.openai.com/v1/audio/transcriptions');if(!$ch)throw new RuntimeException('curl_init_failed');$file=new CURLFile($path,mime_content_type($path)?:'audio/mpeg',basename($path));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.self::key(),'Accept: application/json'],CURLOPT_POSTFIELDS=>['file'=>$file,'model'=>$model,'response_format'=>'json'],CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>120]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_error($ch);curl_close($ch);if($raw===false)throw new RuntimeException('network_error:'.$err);$d=json_decode((string)$raw,true);if(!is_array($d))$d=[];if($status<200||$status>=300)throw new RuntimeException('http_'.$status.':'.substr((string)($d['error']['message']??''),0,300));$text=trim((string)($d['text']??''));if($text==='')throw new RuntimeException('stt_empty_transcript');return ['provider'=>'openai','text'=>$text,'model'=>$model];}
