    public static function embedding(string $text,?string $model=null):array{$model=trim((string)$model)?:'text-embedding-3-small';$r=HttpClient::json('POST','https://api.openai.com/v1/embeddings',['Authorization'=>'Bearer '.self::key()],['model'=>$model,'input'=>pb_substr(trim($text),0,12000)],60);$v=$r['data'][0]['embedding']??null;if(!is_array($v)||count($v)<8)throw new RuntimeException('embedding_vector_missing');return ['provider'=>'openai','vector'=>array_map('floatval',$v),'model'=>(string)($r['model']??$model)];}
    public static function vision(string $prompt,string $imageUrl,?string $model=null,int $max=1500):array{$model=trim((string)$model)?:trim((string)setting('ai.vision_model','gpt-5.6'));$imageUrl=Security::publicUrl($imageUrl);$payload=['model'=>$model,'input'=>[['role'=>'user','content'=>[['type'=>'input_text','text'=>$prompt],['type'=>'input_image','image_url'=>$imageUrl]]]],'max_output_tokens'=>$max,'store'=>false];$r=HttpClient::json('POST','https://api.openai.com/v1/responses',['Authorization'=>'Bearer '.self::key()],$payload,90);$text='';foreach((array)($r['output']??[]) as $o)foreach((array)($o['content']??[]) as $c)if(($c['type']??'')==='output_text')$text.=(string)($c['text']??'');if(trim($text)==='')throw new RuntimeException('vision_empty_output');return ['provider'=>'openai','text'=>trim($text),'model'=>(string)($r['model']??$model)];}
    public static function image(string $prompt,?string $model=null,string $size='1024x1024',string $quality='medium'):array{$model=trim((string)$model)?:trim((string)setting('ai.image_model','gpt-image-2'));$prompt=trim($prompt);if($prompt==='')throw new RuntimeException('image_prompt_required');if(!in_array($size,['1024x1024','1024x1536','1536x1024','auto'],true))$size='1024x1024';$r=HttpClient::json('POST','https://api.openai.com/v1/images/generations',['Authorization'=>'Bearer '.self::key()],['model'=>$model,'prompt'=>pb_substr($prompt,0,12000),'size'=>$size,'quality'=>$quality,'n'=>1],120);$item=(array)($r['data'][0]??[]);$b64=(string)($item['b64_json']??'');$url=(string)($item['url']??'');$path='';if($b64!==''){$bytes=base64_decode($b64,true);if($bytes===false)throw new RuntimeException('image_decode_failed');$path=self::save($bytes,'png','img');}if($path===''&&$url==='')throw new RuntimeException('image_result_missing');return ['provider'=>'openai','model'=>$model,'path'=>$path?:null,'url'=>$url?:null,'revised_prompt'=>$item['revised_prompt']??null];}
}
